#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include "ata_mock_src.c"      /* generated by run_host_tests.sh: the real ata.c with port I/O replaced by the mock below */

/* ---- mock IDE controller per the ATA spec (two-deep register FIFOs for LBA48) ---- */
static int dfd;
static struct { uint8_t cur, prev; } sc, lo, mid, hi;
static uint8_t drive_reg, status = 0x50, last_cmd; static uint64_t cur_lba; static uint32_t left; static int is_write;
static int stale = 0, busy_reads = 0; static uint8_t stale_val = 0x50;   /* real drives show the PREVIOUS status for ~400ns after a transfer step */
static uint64_t dec_lba; static uint32_t dec_count; static int dec_used48; static int cmds_seen;
/* multiple-sector write model: a virtual drive turns each DRQ block into ONE host write
 * (QEMU: WRITE SECTORS blocks are 1 sector, WRITE MULTIPLE blocks are `mult` sectors) */
static uint8_t mock_mult = 0, last_write_cmd = 0; static int is_multi = 0; static uint32_t host_writes = 0;
static int mock_mode = 0;   /* 0 normal; 1 SET MULTIPLE aborts; 2 multi blocks silently lose their last sector */
static void push(typeof(sc)* r, uint8_t v) { r->prev = r->cur; r->cur = v; }
void outb(uint16_t p, uint8_t v) {
    switch (p) {
    case ATA_PRIMARY_DRIVE: drive_reg = v; break;
    case ATA_PRIMARY_SECCOUNT: push(&sc, v); break;
    case ATA_PRIMARY_LBA_LO: push(&lo, v); break;
    case ATA_PRIMARY_LBA_MID: push(&mid, v); break;
    case ATA_PRIMARY_LBA_HI: push(&hi, v); break;
    case ATA_PRIMARY_COMMAND:
        last_cmd = v; cmds_seen++;
        if (v == 0x20 || v == 0x30 || v == 0xC5) {
            if (!(drive_reg & 0x40)) { fprintf(stderr, "MOCK: LBA28 cmd without LBA bit\n"); exit(3); }
            dec_lba = lo.cur | (mid.cur << 8) | (hi.cur << 16) | ((uint64_t)(drive_reg & 0xF) << 24);
            dec_count = sc.cur ? sc.cur : 256; dec_used48 = 0; is_write = (v == 0x30 || v == 0xC5);
            is_multi = (v == 0xC5); if (is_write) last_write_cmd = v;
            cur_lba = dec_lba; left = dec_count; status = 0x58;
            if (v == 0xC5 && mock_mult == 0) { status = 0x51; left = 0; }          /* WRITE MULTIPLE before SET MULTIPLE: abort */
        } else if (v == 0x24 || v == 0x34 || v == 0x39) {
            if (!(drive_reg & 0x40)) { fprintf(stderr, "MOCK: LBA48 cmd without LBA bit\n"); exit(3); }
            dec_lba = (uint64_t)lo.cur | ((uint64_t)mid.cur << 8) | ((uint64_t)hi.cur << 16) |
                      ((uint64_t)lo.prev << 24) | ((uint64_t)mid.prev << 32) | ((uint64_t)hi.prev << 40);
            dec_count = sc.cur | (sc.prev << 8); if (!dec_count) dec_count = 65536;
            dec_used48 = 1; is_write = (v == 0x34 || v == 0x39);
            is_multi = (v == 0x39); if (is_write) last_write_cmd = v;
            cur_lba = dec_lba; left = dec_count; status = 0x58;
            if (v == 0x39 && mock_mult == 0) { status = 0x51; left = 0; }
        } else if (v == 0xC6) {                                                      /* SET MULTIPLE MODE */
            uint8_t n = sc.cur;
            if (mock_mode == 1 || n > 16 || (n & (n - 1))) status = 0x51;           /* abort: unsupported / not a power of two <= 16 */
            else { mock_mult = n; status = 0x50; }
            stale_val = 0x50; stale = 4; busy_reads = 2;
        } else if (v == 0xE7 || v == 0xEA) {
            if (left > 0) { fprintf(stderr, "MOCK: FLUSH issued in the middle of a transfer (%u sectors still pending) -- illegal on real drives\n", left); exit(5); }
            stale_val = status; stale = 4; busy_reads = 2;
        }
        break;
    }
}
uint8_t inb(uint16_t p) {
    if (p != ATA_PRIMARY_STATUS && p != ATA_PRIMARY_CTRL) return 0;
    if (stale > 0) { stale--; return stale_val; }      /* stale window: only a driver that waits ~400ns skips it */
    if (busy_reads > 0) { busy_reads--; return 0x80; } /* then BSY while the drive digests the data */
    return status;
}
uint16_t inw(uint16_t p) { (void)p; return 0; }
void outw(uint16_t p, uint16_t v) { (void)p; (void)v; }
void insw(uint16_t p, void* a, uint32_t n) {
    (void)p; if (n != 256 || is_write || !left) { fprintf(stderr, "MOCK: bad insw\n"); exit(3); }
    if (pread(dfd, a, 512, (off_t)(cur_lba * 512)) != 512) memset(a, 0, 512);
    cur_lba++; if (--left == 0) status = 0x50;
}
void outsw(uint16_t p, const void* a, uint32_t n) {
    (void)p; if (!is_write || !left) { fprintf(stderr, "MOCK: bad outsw (no write transfer pending)\n"); exit(3); }
    uint32_t k;
    if (is_multi) {
        if (!n || n % 256) { fprintf(stderr, "MOCK: WRITE MULTIPLE data not a whole number of sectors\n"); exit(3); }
        k = n / 256;
        uint32_t want = left < mock_mult ? left : mock_mult;
        if (k != want) { fprintf(stderr, "MOCK: WRITE MULTIPLE block of %u sectors, the drive expected %u\n", k, want); exit(3); }
    } else {
        if (n != 256) { fprintf(stderr, "MOCK: WRITE SECTORS must move exactly one sector per DRQ block\n"); exit(3); }
        k = 1;
    }
    /* The drive is still digesting the previous block until the stale+busy window has been read out. */
    if (stale || busy_reads) { fprintf(stderr, "MOCK: data pushed while the drive was still busy (driver skipped the ~400ns settle delay)\n"); exit(6); }
    for (uint32_t i = 0; i < k; i++) {
        if (mock_mode == 2 && is_multi && k > 1 && i == k - 1) continue;      /* faulty drive: last sector of the block is lost */
        if (pwrite(dfd, (const uint8_t*)a + i * 512, 512, (off_t)((cur_lba + i) * 512)) != 512) exit(4);
    }
    host_writes += is_multi ? 1 : k;
    cur_lba += k; left -= k; stale_val = 0x58; stale = 4; busy_reads = 2;
    if (left == 0) status = 0x50;
}

static int fails = 0;
static int drv_mult = 0;   /* what the driver was told: 0 = plain writes, N = WRITE MULTIPLE with N-sector blocks */
static void check(uint64_t lba, uint8_t count, int expect48) {
    uint8_t w[255 * 512], r[255 * 512];
    for (int i = 0; i < count * 512; i++) w[i] = (uint8_t)(lba * 31 + i * 7 + count);
    int c0 = cmds_seen; uint32_t hw0 = host_writes;
    int rc = ata_write_sectors(lba, count, w);
    int multi = drv_mult > 1 && count > 1;
    uint8_t want_cmd = multi ? (expect48 ? 0x39 : 0xC5) : (expect48 ? 0x34 : 0x30);
    uint32_t want_hw = multi ? (count + drv_mult - 1) / drv_mult : count;
    int wcmds = cmds_seen - c0;                 /* must be exactly 2: the write, then ONE flush */
    int ok = (rc == 0 && wcmds == 2 && last_write_cmd == want_cmd && host_writes - hw0 == want_hw && dec_lba == lba && dec_count == count && dec_used48 == expect48 && last_cmd == (expect48 ? 0xEA : 0xE7));
    memset(r, 0, sizeof r);
    c0 = cmds_seen;
    int rr = ata_read_sectors(lba, count, r);
    ok = ok && (cmds_seen - c0) == 1 && rr == 0 && dec_lba == lba && dec_count == count && dec_used48 == expect48 && !memcmp(w, r, count * 512);
    printf("%s lba=%-12llu count=%-3u -> %s decoded=%llu %s  %s, %u host write(s)\n", ok ? "ok  " : "FAIL", (unsigned long long)lba, count,
           dec_used48 ? "LBA48" : "LBA28", (unsigned long long)dec_lba, expect48 ? "(expected 48)" : "(expected 28)",
           multi ? "WRITE MULTIPLE" : "WRITE SECTORS", host_writes - hw0);
    if (!ok) fails++;
}
static void run_address_checks(void) {
    check(0, 1, 0); check(131072, 8, 0); check(12345, 255, 0);
    check(0x0FFFFFFEull, 1, 0);                                    /* last sector reachable with 28-bit */
    check(0x0FFFFFFFull, 1, 0);                                    /* lba+count == 2^28 exactly: still 28-bit */
    check(0x0FFFFFFFull, 2, 1);                                    /* crosses the boundary -> must be 48-bit */
    check(0x10000000ull, 1, 1); check(0x10000000ull, 8, 1);
    check(1258463296ull, 8, 1);                                    /* ~600GB */
    check(0x123456789ull, 8, 1);                                   /* needs bits above 32 */
    check(0x00FFFFFFFFull, 255, 1);
    check(777, 17, 0);                                             /* not a multiple of the block size: short last block */
}
static void expect(int cond, const char* msg) { printf("%s %s\n", cond ? "ok  " : "FAIL", msg); if (!cond) fails++; }
static int sectors_equal(const uint8_t* ref, uint32_t n) {         /* is disk sector 0..n-1 still `ref`? */
    uint8_t d[16 * 512]; if (pread(dfd, d, n * 512, 0) != (ssize_t)(n * 512)) return 0; return !memcmp(d, ref, n * 512);
}
int main(void) {
    dfd = open("/tmp/youos_ata_mockdisk.img", O_RDWR | O_CREAT, 0644); ftruncate(dfd, (off_t)1 << 41);
    ata_lba48 = 1; ata_sectors = (uint64_t)1 << 35;                /* a 2TB-sector-count drive */

    printf("--- plain WRITE SECTORS\n");
    ata_mult = 0; mock_mult = 0; drv_mult = 0;
    run_address_checks();
    printf("--- WRITE MULTIPLE, 16 sectors per block\n");
    ata_mult = 16; mock_mult = 16; drv_mult = 16;
    run_address_checks();
    { uint32_t a = host_writes; uint8_t b[255 * 512]; memset(b, 7, sizeof b);
      ata_write_sectors(5000, 255, b); uint32_t m = host_writes - a;
      ata_mult = 0; a = host_writes; ata_write_sectors(5000, 255, b); uint32_t sgl = host_writes - a; ata_mult = 16;
      expect(m * 15 < sgl, "255 sectors: WRITE MULTIPLE needs far fewer host writes than WRITE SECTORS");
      printf("      (host writes for 255 sectors: plain=%u, multiple=%u)\n", sgl, m); }

    printf("--- boot-time enable + self-test (ata_enable_multiple)\n");
    /* a 512MB drive: the self-test uses 16 all-zero sectors near the end of the disk */
    ata_lba48 = 0; ata_sectors = 1u << 20; ata_mult = 0; mock_mult = 0; mock_mode = 0;
    uint64_t scratch = ((ata_sectors - 128) & ~15ull);
    uint8_t d16[16 * 512], z16[16 * 512], junk[16 * 512]; memset(z16, 0, sizeof z16);
    for (int i = 0; i < 16 * 512; i++) junk[i] = (uint8_t)(i * 7 + 3);
    pwrite(dfd, z16, sizeof z16, (off_t)(scratch * 512));
    expect(ata_enable_multiple(16) == 16 && ata_multiple_sectors() == 16 && mock_mult == 16, "normal drive: multiple mode enabled (16)");
    pread(dfd, d16, sizeof d16, (off_t)(scratch * 512));
    expect(!memcmp(d16, z16, sizeof d16), "...and the scratch sectors were zeroed again afterwards");
    ata_mult = 0; mock_mult = 0;
    expect(ata_enable_multiple(8) == 8 && mock_mult == 8, "drive advertising 8: enabled with 8-sector blocks");
    ata_mult = 0; mock_mult = 0;
    expect(ata_enable_multiple(1) == -1 && ata_multiple_sectors() == 0, "drive advertising 1: not used");
    mock_mode = 1; ata_mult = 0; mock_mult = 0;
    expect(ata_enable_multiple(16) == -1 && ata_multiple_sectors() == 0, "drive rejects SET MULTIPLE: falls back to plain writes");
    mock_mode = 2; ata_mult = 0; mock_mult = 0;
    expect(ata_enable_multiple(16) == -1 && ata_multiple_sectors() == 0, "drive that LOSES part of multi-sector writes: self-test catches it, multiple mode stays off");
    pread(dfd, d16, sizeof d16, (off_t)(scratch * 512));
    expect(!memcmp(d16, z16, sizeof d16), "...and the scratch sectors are back to zeros");
    mock_mode = 0;
    /* the preferred scratch region holds data: it must be left alone and another one used */
    pwrite(dfd, junk, sizeof junk, (off_t)(scratch * 512));
    ata_mult = 0; mock_mult = 0;
    expect(ata_enable_multiple(16) == 16, "scratch region in use (non-zero): a different region is used");
    pread(dfd, d16, sizeof d16, (off_t)(scratch * 512));
    expect(!memcmp(d16, junk, sizeof d16), "...and the in-use sectors were not touched");
    /* every candidate region holds data: refuse rather than risk it */
    for (int t = 1; t < 4; t++) pwrite(dfd, junk, sizeof junk, (off_t)((scratch - (uint64_t)t * 128) * 512));
    ata_mult = 0; mock_mult = 0;
    expect(ata_enable_multiple(16) == -1 && ata_multiple_sectors() == 0, "no all-zero scratch region anywhere: multiple mode not enabled");
    for (int t = 0; t < 4; t++) pwrite(dfd, z16, sizeof z16, (off_t)((scratch - (uint64_t)t * 128) * 512));

    printf("--- runtime fallback\n");
    { uint8_t w[8 * 512], r[8 * 512]; for (int i = 0; i < 8 * 512; i++) w[i] = (uint8_t)(i * 3 + 1);
      ata_mult = 16; mock_mult = 0;                                /* driver believes multiple mode is on, the drive has forgotten it */
      int rc = ata_write_sectors(9000, 8, w);
      expect(rc == 0 && ata_multiple_sectors() == 0, "drive aborts WRITE MULTIPLE mid-session: driver turns it off and redoes the write");
      pread(dfd, r, sizeof r, (off_t)9000 * 512);
      expect(!memcmp(w, r, sizeof w), "...and the data is correct on disk"); }

    printf("--- error handling\n");
    ata_mult = 0; mock_mult = 0; drv_mult = 0; ata_lba48 = 0; ata_sectors = (uint64_t)1 << 35;
    uint8_t buf[2048];
    int rc = ata_read_sectors(0x10000000ull, 1, buf);
    printf("%s high LBA on a drive WITHOUT lba48 -> rc=%d (expected -1)\n", rc == -1 ? "ok  " : "FAIL", rc); if (rc != -1) fails++;
    ata_lba48 = 1; ata_sectors = 0x20000000ull;
    rc = ata_read_sectors(0x20000000ull - 1, 2, buf);
    printf("%s read past end of 48-bit drive -> rc=%d (expected -1)\n", rc == -1 ? "ok  " : "FAIL", rc); if (rc != -1) fails++;
    printf("%s\n", fails ? "SOME CHECKS FAILED" : "ALL ATA CHECKS PASSED"); return fails;
}
